contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address otherOwner) public payable {
        require(newOwner != address(this));
        bool ok = c.setOwner(newOwner);
        address current = c.owner();
        bool second;
        try c.setOwner(otherOwner) { second = true; } catch { second = false; }
        assert(ok && current == newOwner && !second && c.owner() == newOwner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address currentOwner) public {
        require(newOwner != address(0));
        c.setOwner(currentOwner);
        address before = c.owner();
        bool reverted;
        // caller is this contract, not currentOwner, so the call must revert
        if (address(this) != currentOwner) {
            try c.setOwner(newOwner) { reverted = false; }
            catch { reverted = true; }
            assert(reverted && c.owner() == before);
        } else {
            bool ok = c.setOwner(newOwner);
            assert(ok && c.owner() == newOwner);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address nonOwner, address newOwner) public {
        require(nonOwner != address(this));
        require(nonOwner != address(0));
        // c's owner is initially address(this); transfer it away
        c.setOwner(nonOwner);
        address before = c.owner();
        // now this contract is NOT the owner, so this call must revert
        bool reverted;
        try c.setOwner(newOwner) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.owner() == before && before == nonOwner);
    }
    receive() external payable {}
}

